export const screeningStatuses=['no_growth','growth_detected','pending','retest_recommended'];
// Rendering is pure so reports can be checked without a browser or database.
export function renderReport(r,{tr,num,esc,code,locationName,lang,placeholder=false}){
 const status=screeningStatuses.includes(r.screening_status)?r.screening_status:'pending';
 const date=value=>value?num(String(value).slice(0,10)):tr('notProvided');
 const safePhoto=typeof r.photo_url==='string'&&(/^https:\/\//i.test(r.photo_url)||/^\/api\/media\/[a-f0-9-]{36}$/.test(r.photo_url));
 const metrics=[[tr('coliform'),tr(r.coliform_status==='detected'?'detected':r.coliform_status==='not_detected'?'notDetected':'notTested')],[tr('ph'),r.ph==null?null:num(r.ph)],[tr('tds'),r.tds==null?null:`${num(r.tds)} ${tr('mg')}`],[tr('turbidity'),r.turbidity==null?null:`${num(r.turbidity)} ${tr('ntu')}`]];
 return `<article class="testing-report"><header class="screening-banner screening-${status}"><span class="eyebrow">${tr('screeningLabel')}</span><h2>${tr(status)}</h2></header><div class="testing-body"><dl class="testing-fields"><div class="testing-source"><dt>${tr('sourceLocation')}</dt><dd><b>${esc(code)}</b><span>${esc(locationName)}</span></dd></div><div><dt>${tr('lastTested')}</dt><dd>${date(r.tested_at)}</dd></div><div><dt>${tr('nextScreening')}</dt><dd>${r.next_screening_at?date(r.next_screening_at):tr('notScheduled')}</dd></div></dl><section class="test-evidence"><h3>${tr('providedResult')}</h3>${safePhoto?`<a href="${esc(r.photo_url)}" target="_blank" rel="noopener noreferrer" aria-label="${tr('openImage')}"><img src="${esc(r.photo_url)}" alt="${tr('photo')} ${esc(code)}" loading="lazy"></a>`:`<div class="missing-image"><span aria-hidden="true">▤</span><p>${tr('noImage')}</p></div>`}</section>${placeholder?`<p class="report-footnote">${tr('unpublished')}</p>`:`<details class="extra-results"><summary>${tr('details')}</summary>${r.sampled_at?`<p>${tr('sampled')}: ${date(r.sampled_at)}</p>`:''}${r.laboratory?`<p>${esc((lang==='bn'?r.laboratory_bn:null)||r.laboratory)}</p>`:''}<dl>${metrics.filter(([,v])=>v!=null).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${r.notes?`<p>${esc((lang==='bn'?r.notes_bn:null)||r.notes)}</p>`:''}</details>`}</div></article>`;
}
